import{z as B,x as A,o as E,c as p,q as s,j as i,D as e,d as t,s as o,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"CMOS 反相器","description":"","frontmatter":{"title":"CMOS 反相器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cmos-inverter.md","filePath":"cs/cmos-inverter.md","lastUpdated":1791413859000}'),d={name:"cs/cmos-inverter.md"};function m(C,a,S,c,O,h){const n=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=s('<h1 id="cmos-反相器" tabindex="-1">CMOS 反相器 <a class="header-anchor" href="#cmos-反相器" aria-label="Permalink to &quot;CMOS 反相器&quot;">​</a></h1><div class="epigraph"><p>一个 pMOS 上拉、一个 nMOS 下拉，中间那根线才是稳定的 0 与 1；静态 CMOS 几乎不在稳态耗直流。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/interpolation-runge">插值与龙格现象</a>把数值计算收到多项式拟合的边界。信息与离散更早已经结束。本课不重讲条件数，也不从半导体物理的能带另起。缺口是：程序与比特已经会写，布尔课的「非」还没有<strong>器件</strong>。数字逻辑与计算机组成从这里开始：先实现一个反相器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>布尔 \\(\\bar x\\) 是函数。硅上要把电压映射回两个区间。缺口因此不是新的公理，而是一对互补晶体管：输入高则 nMOS 导通把输出拉到地，pMOS 截止；输入低则相反，输出拉到电源。互补使得稳态没有从电源到地的直流通路（忽略漏电）。<span class="marginnote">术语翻译：nMOS 是「输入高才导通」的开关，专职把输出往下拉到地；pMOS 正相反，「输入低才导通」，专职把输出往上拉到电源。两管极性互补、永远一开一关——「互补金属氧化物半导体」（CMOS）的名字就是这么来的。</span></p><p>本课只钉这一格。与非、或非、万能门是<a href="/cs/nand-universal">下一课</a>。阈值、传输特性画到「有噪声容限」为止，不把短沟道模型展开。</p><h3 id="反相器不是「一个晶体管」" tabindex="-1">反相器不是「一个晶体管」 <a class="header-anchor" href="#反相器不是「一个晶体管」" aria-label="Permalink to &quot;反相器不是「一个晶体管」&quot;">​</a></h3><p>单 nMOS 加电阻上拉是 NMOS 逻辑，稳态有电流。CMOS 用 pMOS 代替电阻，极性相反。把反相当成开集电极或模拟放大器，会把后课的恢复性电平说错：数字要的是把中间电压推回轨。</p><p><span class="marginnote">Harris 第 1 章用 CMOS 反相器当数字抽象的物理锚。本课只承认有 p 管 n 管两种开关，不把工艺步骤当内容。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>符号：pMOS 源接 \\(V_{DD}\\)，nMOS 源接地，栅接在一起为输入，漏接在一起为输出。转移曲线中间有高增益区，两边饱和到轨。噪声容限定义为输入还能被当成合法 0/1 的余量。<span class="marginnote">直觉类比：转移曲线中间的高增益区像陡坡——电压一旦被噪声蹭进这一段，就被迅速推向最近的轨道。这就是「恢复性」：走样的信号过几级门自动回到干净的 0 或 1，数字信号因此能一级级传递而不腐坏。</span></p>',11)),(E(),i(l,null,{default:e(()=>[o(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIT%5B%22%E9%80%BB%E8%BE%91%E9%9D%9E%22%5D%20--%3E%20CMOS%5B%22pMOS%20%E4%B8%8A%E6%8B%89%20%2B%20nMOS%20%E4%B8%8B%E6%8B%89%22%5D%0A%20%20CMOS%20--%3E%20RAIL%5B%22%E8%BE%93%E5%87%BA%E9%9D%A0%E8%BF%91%E7%94%B5%E6%BA%90%E6%88%96%E5%9C%B0%22%5D%0A%20%20RAIL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B8%8E%E9%9D%9E%E4%B8%87%E8%83%BD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"恢复性：被噪声推离轨的电压，经过一级（或奇数级）反相器可以拉回。这是第一课「判决」的电路实现。延迟来自对负载电容的充放电，下一课以后的门时延把这一格量化；本课只承认电容存在，不写 \\(t_{pd}=RC\\)。",-1)),a[5]||(a[5]=r("p",null,"功耗：动态是 \\(CV^2f\\)，静态理想为零。漏电使静态非零，本课承认但不建模。",-1)),(E(),i(l,null,{default:e(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%7B%22%E8%BE%93%E5%85%A5%E6%98%AF%E9%AB%98%E8%BF%98%E6%98%AF%E4%BD%8E%EF%BC%9F%22%7D%20--%3E%7C%22%E9%AB%98%22%7C%20NC%5B%22nMOS%20%E5%AF%BC%E9%80%9A%EF%BC%8CpMOS%20%E6%88%AA%E6%AD%A2%22%5D%0A%20%20NC%20--%3E%20LOW%5B%22%E8%BE%93%E5%87%BA%E7%BB%8F%20nMOS%20%E6%94%BE%E7%94%B5%E5%88%B0%E5%9C%B0%EF%BC%9A0%22%5D%0A%20%20IN%20--%3E%7C%22%E4%BD%8E%22%7C%20PC%5B%22pMOS%20%E5%AF%BC%E9%80%9A%EF%BC%8CnMOS%20%E6%88%AA%E6%AD%A2%22%5D%0A%20%20PC%20--%3E%20HIGH%5B%22%E8%BE%93%E5%87%BA%E7%BB%8F%20pMOS%20%E5%85%85%E7%94%B5%E5%88%B0%E7%94%B5%E6%BA%90%EF%BC%9A1%22%5D%0A%20%20LOW%20--%3E%20NOPATH%5B%22%E6%88%AA%E6%AD%A2%E7%9A%84%E9%82%A3%E7%AE%A1%E6%8C%A1%E4%BD%8F%E7%94%B5%E6%BA%90%E5%88%B0%E5%9C%B0%E7%9A%84%E7%9B%B4%E6%B5%81%E9%80%9A%E8%B7%AF%22%5D%0A%20%20HIGH%20--%3E%20NOPATH%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">这张图回答「两种输入下电流各走哪条路、为什么稳态不耗直流」。数字实例看动态功耗：负载电容 10 fF、电压 1 V、每秒翻转 10 亿次，这一根线的功耗约 \\(10\\times10^{-15}\\times 1^2\\times 10^9 = 10\\) µW——单根不起眼，亿万个翻转节点攒起来就是芯片热量的主要来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲工艺节点纳米数、FinFET。模拟偏置、差分对不属于主干。时序电路仍没有时钟。</p><p>后课默认：逻辑门的原子是 CMOS 复合物；稳态输出在轨附近；非由反相器实现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CMOS 反相器：p 上拉 n 下拉，稳态几乎无直流。</li><li>高增益区提供噪声容限与电平恢复。</li><li>与非/或非网络、延迟公式是后课。</li><li>出处：Harris and Harris, <em>Digital Design and Computer Architecture</em>。</li></ul>',6))])}const D=B(d,[["render",m]]);export{u as __pageData,D as default};
